CREATE OR REPLACE FUNCTION public.imp_permiso(_accion text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND activo) AND (EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND lower(email)='adgral@convertipap.site') OR CASE _accion WHEN 'catalogo' THEN EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND lower(email) IN ('gcalidad@convertipap.site','msramosixt@convertipap.site')) WHEN 'editar' THEN public.has_role(auth.uid(),'calidad') OR public.has_role(auth.uid(),'calidad_operativo') WHEN 'capturar' THEN (public.has_role(auth.uid(),'capturista') OR public.has_role(auth.uid(),'calidad') OR public.has_role(auth.uid(),'calidad_operativo')) AND public.can_access_module(auth.uid(),'control_calidad') WHEN 'leer' THEN public.can_access_module(auth.uid(),'reportes') OR ((public.has_role(auth.uid(),'capturista') OR public.has_role(auth.uid(),'calidad') OR public.has_role(auth.uid(),'calidad_operativo')) AND public.can_access_module(auth.uid(),'control_calidad')) WHEN 'importar' THEN false ELSE false END) $$;
REVOKE ALL ON FUNCTION public.imp_permiso(text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.imp_permiso(text) TO authenticated, service_role;
CREATE TABLE public.imp_proveedores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre text NOT NULL CHECK(length(btrim(nombre)) BETWEEN 1 AND 120), creado_por uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.imp_proveedores TO authenticated; GRANT ALL ON public.imp_proveedores TO service_role; ALTER TABLE public.imp_proveedores ENABLE ROW LEVEL SECURITY; CREATE POLICY imp_proveedor_lectura ON public.imp_proveedores FOR SELECT TO authenticated USING(public.imp_permiso('leer')); CREATE UNIQUE INDEX imp_proveedor_nombre ON public.imp_proveedores(lower(btrim(nombre)));
CREATE TABLE public.imp_productos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo text NOT NULL CHECK(length(btrim(codigo)) BETWEEN 2 AND 64), sku_referencia text CHECK(length(sku_referencia)<=64), revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.imp_productos TO authenticated; GRANT ALL ON public.imp_productos TO service_role; ALTER TABLE public.imp_productos ENABLE ROW LEVEL SECURITY; CREATE POLICY imp_producto_lectura ON public.imp_productos FOR SELECT TO authenticated USING(public.imp_permiso('leer')); CREATE UNIQUE INDEX imp_producto_codigo ON public.imp_productos(lower(btrim(codigo)));
CREATE TABLE public.imp_bobinas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), numero integer NOT NULL UNIQUE CHECK(numero>0), folio text GENERATED ALWAYS AS (lpad(numero::text,greatest(5,length(numero::text)),'0') || '-00') STORED UNIQUE, maquina text NOT NULL DEFAULT 'MP-00' CHECK(maquina='MP-00'), proveedor_id uuid NOT NULL REFERENCES public.imp_proveedores(id), producto_id uuid NOT NULL REFERENCES public.imp_productos(id), producto_codigo text NOT NULL, proveedor_nombre text NOT NULL, sku text CHECK(length(sku)<=64), sku_referencia text, analista text, observaciones text, turno text CHECK(turno IN ('1','2','3')), planta_codigo text CHECK(planta_codigo IN ('TLX','IXT')), fecha date NOT NULL, estado text NOT NULL CHECK(estado IN ('liberada','rechazada','concesion')), valores jsonb NOT NULL DEFAULT '{}', capturado_por uuid, capturado_at timestamptz, registrado_at timestamptz NOT NULL DEFAULT now(), revision integer NOT NULL DEFAULT 1, origen text NOT NULL DEFAULT 'captura' CHECK(origen IN ('captura','excel')), fuente_sha256 text, fuente_fila integer, folio_original text, estado_original text, datos_originales jsonb, UNIQUE(fuente_sha256,fuente_fila));
GRANT SELECT ON public.imp_bobinas TO authenticated; GRANT ALL ON public.imp_bobinas TO service_role; ALTER TABLE public.imp_bobinas ENABLE ROW LEVEL SECURITY; CREATE POLICY imp_bobina_lectura ON public.imp_bobinas FOR SELECT TO authenticated USING(public.imp_permiso('leer'));
CREATE INDEX imp_bobina_fecha ON public.imp_bobinas(fecha,numero);
CREATE TABLE public.imp_eventos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bobina_id uuid REFERENCES public.imp_bobinas(id), accion text NOT NULL, usuario_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), motivo text NOT NULL, antes jsonb, despues jsonb);
GRANT SELECT ON public.imp_eventos TO authenticated; GRANT ALL ON public.imp_eventos TO service_role; ALTER TABLE public.imp_eventos ENABLE ROW LEVEL SECURITY; CREATE POLICY imp_eventos_lectura ON public.imp_eventos FOR SELECT TO authenticated USING(public.imp_permiso('leer'));
CREATE TABLE public.imp_contador(id boolean PRIMARY KEY DEFAULT true CHECK(id), siguiente integer NOT NULL DEFAULT 760 CHECK(siguiente>=760));
GRANT SELECT ON public.imp_contador TO authenticated; GRANT ALL ON public.imp_contador TO service_role; ALTER TABLE public.imp_contador ENABLE ROW LEVEL SECURITY; CREATE POLICY imp_contador_lectura ON public.imp_contador FOR SELECT TO authenticated USING(public.imp_permiso('leer'));
CREATE OR REPLACE FUNCTION public.imp_validar_valores(_v jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; v jsonb; BEGIN IF jsonb_typeof(_v)<>'object' THEN RAISE EXCEPTION 'Valores inválidos'; END IF; FOR k,v IN SELECT * FROM jsonb_each(_v) LOOP IF k NOT IN ('peso_base','r457','a','b','peso_bobina','ancho_util') OR (v<>'null'::jsonb AND jsonb_typeof(v)<>'number') THEN RAISE EXCEPTION 'Variable o valor inválido: %',k; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.imp_validar_valores(jsonb) FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.imp_catalogo_guardar(_tipo text,_nombre text,_sku text DEFAULT NULL,_id uuid DEFAULT NULL,_revision integer DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_antes jsonb; v_despues jsonb; BEGIN IF NOT public.imp_permiso(CASE WHEN _tipo='proveedor' THEN 'capturar' ELSE 'catalogo' END) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; IF _tipo='proveedor' THEN IF _id IS NOT NULL THEN RAISE EXCEPTION 'Edición de proveedores no autorizada'; END IF; INSERT INTO public.imp_proveedores(nombre,creado_por) VALUES(btrim(_nombre),auth.uid()) RETURNING id,to_jsonb(imp_proveedores.*) INTO v_id,v_despues; ELSIF _tipo='producto' THEN IF _id IS NULL THEN INSERT INTO public.imp_productos(codigo,sku_referencia) VALUES(btrim(_nombre),nullif(btrim(_sku),'')) RETURNING id,to_jsonb(imp_productos.*) INTO v_id,v_despues; ELSE SELECT to_jsonb(p.*) INTO v_antes FROM public.imp_productos p WHERE id=_id FOR UPDATE; UPDATE public.imp_productos SET codigo=btrim(_nombre),sku_referencia=nullif(btrim(_sku),''),revision=revision+1 WHERE id=_id AND revision=_revision RETURNING id,to_jsonb(imp_productos.*) INTO v_id,v_despues; IF v_id IS NULL THEN RAISE EXCEPTION 'El producto cambió. Actualice antes de guardar.'; END IF; END IF; ELSE RAISE EXCEPTION 'Catálogo inválido'; END IF; INSERT INTO public.imp_eventos(accion,usuario_id,motivo,antes,despues) VALUES('catalogo_'||_tipo,auth.uid(),'Gestión de catálogo Bobinas Madre Imp',v_antes,v_despues); RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.imp_catalogo_guardar(text,text,text,uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.imp_catalogo_guardar(text,text,text,uuid,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.imp_guardar(_id uuid,_datos jsonb,_revision integer DEFAULT NULL,_motivo text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.imp_bobinas; p public.imp_productos; s public.imp_proveedores; n integer; v_antes jsonb; BEGIN PERFORM pg_advisory_xact_lock(247600); SELECT * INTO v FROM public.imp_bobinas WHERE id=_id FOR UPDATE; IF FOUND THEN IF _revision IS NULL AND v.capturado_por=auth.uid() AND v.origen='captura' THEN RETURN v.id; END IF; IF NOT public.imp_permiso('editar') THEN RAISE EXCEPTION 'Edición solo para Calidad y adgral' USING ERRCODE='42501'; END IF; IF v.capturado_at IS NULL OR now()>v.capturado_at+interval '36 hours' THEN RAISE EXCEPTION 'Fuera de la ventana de 36 horas desde captura'; END IF; IF v.revision IS DISTINCT FROM _revision THEN RAISE EXCEPTION 'El registro cambió. Actualice antes de guardar.'; END IF; IF length(btrim(coalesce(_motivo,'')))<10 THEN RAISE EXCEPTION 'Motivo de edición: mínimo 10 caracteres'; END IF; v_antes:=to_jsonb(v); ELSE IF _revision IS NOT NULL THEN RAISE EXCEPTION 'Registro inexistente'; END IF; IF NOT public.imp_permiso('capturar') THEN RAISE EXCEPTION 'Sin permiso de captura' USING ERRCODE='42501'; END IF; INSERT INTO public.imp_contador(id,siguiente) VALUES(true,greatest(760,coalesce((SELECT max(numero)+1 FROM public.imp_bobinas),760))) ON CONFLICT(id) DO NOTHING; SELECT siguiente INTO n FROM public.imp_contador WHERE id=true FOR UPDATE; v.id:=_id; v.numero:=n; v.capturado_por:=auth.uid(); v.capturado_at:=now(); v.origen:='captura'; END IF;
SELECT * INTO p FROM public.imp_productos WHERE id=(_datos->>'producto_id')::uuid; IF NOT FOUND THEN RAISE EXCEPTION 'Producto inexistente'; END IF; SELECT * INTO s FROM public.imp_proveedores WHERE id=(_datos->>'proveedor_id')::uuid; IF NOT FOUND THEN RAISE EXCEPTION 'Proveedor inexistente'; END IF; PERFORM public.imp_validar_valores(_datos->'valores'); IF length(btrim(coalesce(_datos->>'analista','')))=0 OR _datos->>'turno' NOT IN ('1','2','3') OR _datos->>'planta_codigo' NOT IN ('TLX','IXT') THEN RAISE EXCEPTION 'Analista, turno y planta obligatorios'; END IF;
IF v_antes IS NULL THEN INSERT INTO public.imp_bobinas(id,numero,proveedor_id,producto_id,producto_codigo,proveedor_nombre,sku,sku_referencia,analista,observaciones,turno,planta_codigo,fecha,estado,valores,capturado_por,capturado_at) VALUES(v.id,v.numero,s.id,p.id,p.codigo,s.nombre,nullif(btrim(_datos->>'sku'),''),p.sku_referencia,btrim(_datos->>'analista'),_datos->>'observaciones',_datos->>'turno',_datos->>'planta_codigo',(_datos->>'fecha')::date,_datos->>'estado',_datos->'valores',v.capturado_por,v.capturado_at) RETURNING * INTO v; UPDATE public.imp_contador SET siguiente=siguiente+1 WHERE id=true; ELSE UPDATE public.imp_bobinas SET proveedor_id=s.id,producto_id=p.id,producto_codigo=p.codigo,proveedor_nombre=s.nombre,sku=nullif(btrim(_datos->>'sku'),''),sku_referencia=p.sku_referencia,analista=btrim(_datos->>'analista'),observaciones=_datos->>'observaciones',turno=_datos->>'turno',planta_codigo=_datos->>'planta_codigo',fecha=(_datos->>'fecha')::date,estado=_datos->>'estado',valores=_datos->'valores',revision=revision+1 WHERE id=v.id RETURNING * INTO v; END IF;
INSERT INTO public.imp_eventos(bobina_id,accion,usuario_id,motivo,antes,despues) VALUES(v.id,CASE WHEN v_antes IS NULL THEN 'captura' ELSE 'edicion' END,auth.uid(),coalesce(nullif(_motivo,''),nullif(_datos->>'observaciones',''),'Registro de bobina importada'),v_antes,to_jsonb(v)); RETURN v.id; END $$;
REVOKE ALL ON FUNCTION public.imp_guardar(uuid,jsonb,integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.imp_guardar(uuid,jsonb,integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.imp_importar_excel(_sha text,_filas jsonb,_excepciones jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; p uuid; s uuid; n integer; v_id uuid; total integer:=0; anterior public.imp_bobinas; BEGIN IF NOT public.imp_permiso('importar') THEN RAISE EXCEPTION 'Importación solo adgral' USING ERRCODE='42501'; END IF; IF _sha !~ '^[a-f0-9]{64}$' OR jsonb_array_length(_filas)<>759 THEN RAISE EXCEPTION 'Archivo no corresponde al histórico validado de 759 bobinas'; END IF; PERFORM pg_advisory_xact_lock(247600); INSERT INTO public.imp_proveedores(nombre,creado_por) VALUES('Continental',auth.uid()) ON CONFLICT DO NOTHING; SELECT id INTO s FROM public.imp_proveedores WHERE lower(nombre)='continental'; FOR r IN SELECT * FROM jsonb_array_elements(_filas) LOOP n:=(r->>'numero')::integer; IF n NOT BETWEEN 1 AND 759 OR r->>'producto' NOT IN ('PTC31','PSM33','PHR31','PSK32') THEN RAISE EXCEPTION 'Folio o producto histórico inválido'; END IF; PERFORM public.imp_validar_valores(r->'valores'); SELECT * INTO anterior FROM public.imp_bobinas WHERE numero=n; IF FOUND THEN IF anterior.fuente_sha256=_sha AND anterior.fuente_fila=(r->>'fila')::integer AND anterior.datos_originales=r->'original' THEN CONTINUE; ELSE RAISE EXCEPTION 'Folio % ocupado con otro origen; importación detenida',n; END IF; END IF; INSERT INTO public.imp_productos(codigo) VALUES(r->>'producto') ON CONFLICT DO NOTHING; SELECT id INTO p FROM public.imp_productos WHERE codigo=r->>'producto'; INSERT INTO public.imp_bobinas(numero,proveedor_id,producto_id,producto_codigo,proveedor_nombre,fecha,estado,valores,origen,fuente_sha256,fuente_fila,folio_original,estado_original,datos_originales) VALUES(n,s,p,r->>'producto','Continental',(r->>'fecha')::date,r->>'estado',r->'valores','excel',_sha,(r->>'fila')::integer,r->>'folio_original',r->>'estado_original',r->'original') RETURNING id INTO v_id; INSERT INTO public.imp_eventos(bobina_id,accion,usuario_id,motivo,despues) SELECT v_id,'importacion',auth.uid(),'Importación Excel; folio interno -00; Condicionado → Concesión; originales conservados',to_jsonb(b.*) FROM public.imp_bobinas b WHERE id=v_id; total:=total+1; END LOOP; IF (SELECT count(*) FROM public.imp_bobinas WHERE numero BETWEEN 1 AND 759)<>759 THEN RAISE EXCEPTION 'Histórico incompleto'; END IF; INSERT INTO public.imp_contador(id,siguiente) VALUES(true,greatest(760,(SELECT max(numero)+1 FROM public.imp_bobinas))) ON CONFLICT(id) DO UPDATE SET siguiente=greatest(imp_contador.siguiente,excluded.siguiente); INSERT INTO public.imp_eventos(accion,usuario_id,motivo,despues) VALUES('archivo_importado',auth.uid(),'BOBINAS_CONTINENTAL.xlsx: 759 folios validados; celda aislada preservada como excepción, no bobina',jsonb_build_object('sha256',_sha,'nuevos',total,'excepciones',_excepciones)); RETURN total; END $$;
REVOKE ALL ON FUNCTION public.imp_importar_excel(text,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.imp_importar_excel(text,jsonb,jsonb) TO authenticated;